// Banque de questions — QCM style examen OP001 (HEP Vaud)
// Format : 4 propositions (1-4) + "A" (Aucune) + "T" (Toutes).
// Phrases originales, jamais tirées des examens réels ni du catalogue analysé.
//
// Calibrage (v4) — DIFFICULTÉ RELEVÉE, sur retour utilisateur (« trop simple ») :
//   • PIÈGES CONTRE-INTUITIFS : la réponse « évidente » à l'oreille est fausse
//     (après que + indicatif, faire/se voir + infinitif invariable, « en » COD
//     invariable, monter transitif vs intransitif, ne pas penser que + subj...) ;
//   • DISTRACTEURS TRÈS PROCHES : formes quasi jumelles qui exigent une analyse,
//     pas un simple repérage d'intrus ;
//   • « Aucune » / « Toutes » réparties comme dans le réel (~17 %) ;
//   • chaque question porte `why` (raison par option) et a passé une validation
//     indépendante (résolution à l'aveugle, unicité de la réponse).

const RULES = [
  { id: 'orthographe', label: 'Orthographe lexicale & homophones', desc: 'quant/quand, censé/sensé, quoique/quoi que, prêt/près, davantage...' },
  { id: 'modes', label: 'Concordance des modes', desc: 'Subjonctif/indicatif : déclencheurs trompeurs (après que, espérer, ne pas penser...)' },
  { id: 'participe', label: 'Accord du participe passé', desc: 'Pronominaux, faire/se voir + infinitif, « en » COD, monter transitif/intransitif' },
  { id: 'relatifs', label: 'Pronoms relatifs', desc: 'duquel après locution, à qui/en qui, dont abusif, reconstitution' },
  { id: 'pronoms', label: 'Pronoms compléments & sujet implicite', desc: 'y/en, le neutre invariable, ordre des pronoms, participiales détachées' },
  { id: 'eleves', label: "Phrases d'élèves", desc: 'Repérer la phrase correcte parmi des copies réalistes (fautes discrètes, hypercorrections)' },
  { id: 'sujetverbe', label: 'Accord sujet-verbe', desc: 'Sujet éloigné, plus d\'un / moins de deux, c\'est moi qui, sujet inversé' },
  { id: 'adjverbal', label: 'Adjectif verbal & participe présent', desc: 'fatigant/fatiguant, convaincant/convainquant, négligent/négligeant + conjugaison' },
  { id: 'connecteurs', label: 'Connecteurs logiques', desc: 'Cause, conséquence, concession, paires corrélatives, or/aussi/en fait' },
  { id: 'ponctuation', label: 'Ponctuation', desc: 'Virgules interdites et obligatoires, incises, deux-points, relatives' },
];

